div.t-attf-style:
width: #{
                                '10%' if order.state == 'draft' else
                                '32.5%' if order.state == 'scheduled' else
                                '55%' if order.state == 'dispatched' else
                                '77.5%' if order.state == 'in_progress' else
                                '100%'
                            };
